"""Environment factories and rollout wrappers for the three evaluation domains.

These wrappers expose a uniform ``reset()`` / ``step(action)`` interface plus
the task-specific reset behaviour described in the paper:

  * AntMaze: the ant starts in the *centre* of the maze (Appendix C.1), and
    goal-reaching tasks additionally set the D4RL target so that the standard
    environment reward agrees with the task reward;
  * ExORL: the DeepMind Control Suite ``walker`` / ``cheetah`` environments at
    a fixed episode length of 1000 steps;
  * Kitchen: ``kitchen-complete-v0`` with its sparse subtask rewards.
"""

from __future__ import annotations

from typing import Callable, Optional, Sequence

import numpy as np


class GymEnvWrapper:
    """Thin adapter so that ``step`` always returns ``(obs, reward, done, info)``."""

    def __init__(self, env, task=None) -> None:
        self.env = env
        self.task = task

    def reset(self, seed: Optional[int] = None):
        if seed is not None:
            try:
                self.env.seed(seed)
            except Exception:
                pass
        out = self.env.reset()
        obs = out[0] if isinstance(out, tuple) else out
        return np.asarray(obs, dtype=np.float32).reshape(-1)

    def step(self, action):
        out = self.env.step(action)
        if len(out) == 5:  # gymnasium API
            obs, _reward, terminated, truncated, info = out
            return np.asarray(obs, dtype=np.float32).reshape(-1), 0.0, bool(terminated or truncated), info
        obs, reward, done, info = out
        return np.asarray(obs, dtype=np.float32).reshape(-1), reward, bool(done), info


class AntMazeEnvWrapper(GymEnvWrapper):
    """AntMaze rollout environment with the paper's centre reset."""

    def __init__(self, env, task=None, max_episode_steps: int = 2000) -> None:
        super().__init__(env, task)
        self.max_episode_steps = max_episode_steps
        self._step = 0

    def reset(self, seed: Optional[int] = None):
        from fre.tasks.antmaze import center_reset_xy

        obs = super().reset(seed)
        # Move the ant to the centre of the maze.
        try:
            base = self.env.unwrapped
            loco = getattr(base, "wrapped_env", None)
            if loco is not None and hasattr(loco, "set_xy"):
                loco.set_xy(center_reset_xy())
                obs = np.asarray(loco._get_obs(), dtype=np.float32).reshape(-1)
        except Exception:  # pragma: no cover - depends on the installed d4rl
            pass
        self._step = 0
        return obs

    def step(self, action):
        out = super().step(action)
        self._step += 1
        done = bool(out[2]) or self._step >= self.max_episode_steps
        return out[0], out[1], done, out[3]


class AntMazeGoalEnvWrapper(AntMazeEnvWrapper):
    """Additionally exposes the ant's (x, y) position and velocity for logging."""

    @property
    def xy(self) -> np.ndarray:
        return np.asarray(self.env.unwrapped.wrapped_env.get_xy(), dtype=np.float32)


def make_antmaze_env_factory(env_name: str = "antmaze-large-diverse-v2", max_episode_steps: int = 2000):
    """Return ``env_factory(task) -> AntMazeEnvWrapper``."""
    import gym
    import d4rl  # noqa: F401

    def factory(task):
        env = gym.make(env_name)
        wrapper = AntMazeEnvWrapper(env, task, max_episode_steps=max_episode_steps)
        if task is not None and getattr(task, "goal", None) is not None and task.group == "goal-reaching":
            # Match the D4RL target to the task goal so that the environment's
            # own termination behaviour agrees with the evaluation reward.
            try:
                env.unwrapped.set_target(np.asarray(task.goal, dtype=np.float64))
            except Exception:
                pass
        return wrapper

    return factory


def make_exorl_env_factory(domain: str, max_episode_steps: int = 1000):
    """Return ``env_factory(task) -> GymEnvWrapper`` for DMC walker / cheetah."""
    from dm_control import suite

    task_name = {"walker": "walk", "cheetah": "run"}[domain]

    def factory(task):
        env = suite.load(domain_name=domain, task_name=task_name)
        env = _DMControlEpisodeWrapper(env, max_episode_steps)
        return GymEnvWrapper(env, task)

    return factory


class _DMControlEpisodeWrapper:
    """Wrap a dm_control environment behind the gym-style interface.

    dm_control observations are dictionaries; we flatten the ``observations``
    entry (the standard observation vector) in the same order used by the
    ExORL datasets.
    """

    def __init__(self, env, max_episode_steps: int = 1000) -> None:
        self.env = env
        self.max_episode_steps = max_episode_steps
        self._time_step = None
        self._steps = 0
        self._action_spec = env.action_spec()

    def _obs(self) -> np.ndarray:
        return np.asarray(self._time_step.observation["observations"], dtype=np.float32).reshape(-1)

    def reset(self, seed: Optional[int] = None):
        if seed is not None:
            self.env.task._random = np.random.RandomState(seed)
        self._time_step = self.env.reset()
        self._steps = 0
        return self._obs()

    def step(self, action):
        action = np.clip(action, self._action_spec.minimum, self._action_spec.maximum)
        self._time_step = self.env.step(action)
        self._steps += 1
        done = bool(self._time_step.last()) or self._steps >= self.max_episode_steps
        return self._obs(), 0.0, done, {}


def make_kitchen_env_factory(env_name: str = "kitchen-complete-v0", max_episode_steps: int = 280):
    """Return ``env_factory(task) -> GymEnvWrapper`` for D4RL Kitchen."""
    import gym
    import d4rl  # noqa: F401

    def factory(task):
        env = gym.make(env_name)
        return _KitchenEnvWrapper(env, task, max_episode_steps)

    return factory


class _KitchenEnvWrapper(GymEnvWrapper):
    """Kitchen wrapper that reports the sparse reward of a single subtask."""

    def __init__(self, env, task=None, max_episode_steps: int = 280) -> None:
        super().__init__(env, task)
        self.max_episode_steps = max_episode_steps
        self._steps = 0

    def reset(self, seed: Optional[int] = None):
        self._steps = 0
        obs = super().reset(seed)
        if self.task is not None:
            try:
                base = self.env.unwrapped
                base.set_goal(self.task.task_index)
            except Exception:
                pass
        return obs

    def step(self, action):
        out = super().step(action)
        self._steps += 1
        done = bool(out[2]) or self._steps >= self.max_episode_steps
        return out[0], out[1], done, out[3]

"""Per-domain glue: dataset loading, prior construction, task suites, envs.

This module is the single place where the paper's domain-specific choices live
(Appendix C), so that the training / evaluation entry points stay generic.
"""

from __future__ import annotations

from dataclasses import replace
from typing import Callable, Dict, List, Optional, Tuple

import numpy as np
import torch

from fre.configs import TrainConfig
from fre.datasets import OfflineDataset, load_d4rl_dataset, load_exorl_dataset
from fre.reward_functions import RewardPrior, build_prior
from fre.tasks.base import TaskSuite
from fre.tasks.antmaze import (
    ANTMAZE_OBS_DIM,
    make_antmaze_suites,
    xy_from_obs,
)
from fre.tasks.exorl import (
    AUX_DIMS,
    build_antmaze_hint_priors,
    build_exorl_hint_priors,
    make_exorl_suites,
    sample_fixed_goals,
)
from fre.tasks.kitchen import make_kitchen_suite


SUPPORTED_DOMAINS: Tuple[str, ...] = ("antmaze", "walker", "cheetah", "kitchen")


def default_config(domain: str, **overrides) -> TrainConfig:
    """Return the default :class:`TrainConfig` for a domain."""
    config = TrainConfig(domain=domain, **overrides)
    if domain == "antmaze":
        config.env_name = "antmaze-large-diverse-v2"
        # Appendix B: linear rewards exclude the (x, y) position dimensions on
        # AntMaze (their scale caused instability), and the goal-reaching prior
        # uses the maze position with the same distance threshold (2) as the
        # goal-reaching evaluation tasks.
        config.linear_excluded_dims = [0, 1]
        config.goal_dims = [0, 1]
        config.goal_threshold = 2.0
        config.discretize_xy = True
    elif domain in ("walker", "cheetah"):
        config.env_name = domain
        # ExORL goal-reaching uses the Euclidean distance in the normalised
        # observation space with a threshold of 0.1.
        config.goal_threshold = 0.1
        config.discretize_xy = False
    elif domain == "kitchen":
        config.env_name = "kitchen-complete-v0"
        config.discretize_xy = False
    else:
        raise ValueError(f"Unsupported domain '{domain}'. Options: {SUPPORTED_DOMAINS}")
    return config


def build_dataset(config: TrainConfig) -> OfflineDataset:
    """Load the offline dataset for a domain."""
    if config.domain == "antmaze":
        return load_d4rl_dataset("antmaze-large-diverse-v2")
    if config.domain in ("walker", "cheetah"):
        return load_exorl_dataset(
            config.domain,
            algo=config.exorl_algo,
            data_dir=config.exorl_data_dir,
        )
    if config.domain == "kitchen":
        return load_d4rl_dataset("kitchen-complete-v0")
    raise ValueError(f"Unsupported domain '{config.domain}'")


def build_domain_prior(config: TrainConfig, dataset: OfflineDataset) -> RewardPrior:
    """Construct the prior reward distribution for a domain (Sections 4.2-5.4)."""
    goal_sampler = dataset.goal_sampler(np.random.default_rng(config.seed))
    goal_scale = None
    if config.domain in ("walker", "cheetah"):
        # Goal distance is computed on the non-augmented observation space,
        # normalised by the standard deviation of each dimension.
        goal_scale = np.asarray(dataset.observations.std(axis=0), dtype=np.float32)
    hint_priors = None
    hint_ratios = None
    if config.use_hint_priors:
        if config.domain == "antmaze":
            hint_priors = build_antmaze_hint_priors()
        elif config.domain in ("walker", "cheetah"):
            hint_priors = build_exorl_hint_priors(config.domain)
        if hint_priors is not None:
            hint_ratios = {name: 1.0 for name in hint_priors}
            hint_ratios["goal"] = (1.0 - config.hint_ratio) / 3.0 * 3.0
            hint_ratios["lin"] = (1.0 - config.hint_ratio) / 3.0
            hint_ratios["mlp"] = (1.0 - config.hint_ratio) / 3.0
            hint_ratios = {
                **{name: config.hint_ratio / len(hint_priors) for name in hint_priors},
                "goal": (1.0 - config.hint_ratio) / 3.0,
                "lin": (1.0 - config.hint_ratio) / 3.0,
                "mlp": (1.0 - config.hint_ratio) / 3.0,
            }
    return build_prior(
        config.prior_name,
        dataset.encoder_obs_dim,
        goal_sampler,
        goal_threshold=config.goal_threshold,
        goal_dims=config.goal_dims,
        goal_scale=goal_scale,
        linear_excluded_dims=config.linear_excluded_dims,
        ratios=config.prior_ratios,
        hint_priors=hint_priors,
        hint_ratios=hint_ratios,
    )


def build_suites(
    config: TrainConfig,
    dataset: OfflineDataset,
    use_opensimplex: bool = True,
) -> List[TaskSuite]:
    """Build the evaluation task suites that make up Table 1."""
    if config.domain == "antmaze":
        return make_antmaze_suites(max_episode_steps=2000, use_opensimplex=use_opensimplex)
    if config.domain in ("walker", "cheetah"):
        goals = sample_fixed_goals(dataset, num_goals=5, seed=config.seed)
        obs_std = np.asarray(dataset.observations.std(axis=0), dtype=np.float32)
        return make_exorl_suites(
            config.domain, goals=goals, obs_std=obs_std, max_episode_steps=1000
        )
    if config.domain == "kitchen":
        return [make_kitchen_suite()]
    raise ValueError(f"Unsupported domain '{config.domain}'")


def make_env_factory(config: TrainConfig) -> Callable:
    """Return the environment factory used to roll out the trained agent."""
    from fre.envs import (
        make_antmaze_env_factory,
        make_exorl_env_factory,
        make_kitchen_env_factory,
    )

    if config.domain == "antmaze":
        return make_antmaze_env_factory(config.env_name, max_episode_steps=2000)
    if config.domain in ("walker", "cheetah"):
        return make_exorl_env_factory(config.domain, max_episode_steps=1000)
    if config.domain == "kitchen":
        return make_kitchen_env_factory(config.env_name, max_episode_steps=280)
    raise ValueError(f"Unsupported domain '{config.domain}'")


def context_states(
    dataset: OfflineDataset,
    task,
    num_samples: int,
    rng: np.random.Generator,
) -> np.ndarray:
    """Sample the ``(state, reward)`` context set used to encode a downstream task.

    Section 5.2 / Table 1: FRE uses only 32 ``(state, reward)`` pairs at
    evaluation time.
    """
    idx = rng.integers(0, len(dataset), size=num_samples)
    return np.asarray(dataset.encoder_observations[idx], dtype=np.float32)

