#!/usr/bin/env python
"""Aggregate per-seed evaluation JSON files into the paper's result tables.

Reads files named ``<domain>-<prior>-s<seed>.json`` (as produced by
``evaluate_fre.py``), averages each task suite across seeds, and emits
Table 1 / Table 4 style summaries (mean +/- standard deviation over 5 seeds,
with 20 evaluation episodes per seed, matching the paper).
"""

from __future__ import annotations

import argparse
import json
import os
import re
from collections import defaultdict
from typing import Dict, List

import numpy as np


NAME_RE = re.compile(r"^(?P<domain>[a-z]+)-(?P<prior>.+)-s(?P<seed>\d+)\.json$")


def load_results(input_dir: str) -> Dict[str, Dict[str, Dict[int, float]]]:
    """Return ``{domain: {prior: {seed: {suite: score}}}}``."""
    results: Dict[str, Dict[str, Dict[int, Dict[str, float]]]] = defaultdict(
        lambda: defaultdict(dict)
    )
    for fname in sorted(os.listdir(input_dir)):
        match = NAME_RE.match(fname)
        if not match:
            continue
        domain, prior, seed = match.group("domain"), match.group("prior"), int(match.group("seed"))
        with open(os.path.join(input_dir, fname)) as f:
            payload = json.load(f)
        per_suite = {}
        for suite_name, suite in payload.items():
            if isinstance(suite, dict) and "mean" in suite:
                per_suite[suite_name] = float(suite["mean"])
        results[domain][prior][seed] = per_suite
    return results


def aggregate(results) -> Dict[str, Dict[str, Dict[str, Dict[str, float]]]]:
    """``{domain: {prior: {suite: {mean, std, num_seeds}}}}``."""
    out: Dict[str, Dict[str, Dict[str, Dict[str, float]]]] = {}
    for domain, priors in results.items():
        out[domain] = {}
        for prior, seeds in priors.items():
            suites = defaultdict(list)
            for _seed, per_suite in seeds.items():
                for suite, score in per_suite.items():
                    suites[suite].append(score)
            out[domain][prior] = {
                suite: {
                    "mean": float(np.mean(v)),
                    "std": float(np.std(v)),
                    "num_seeds": len(v),
                }
                for suite, v in suites.items()
            }
    return out


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--input-dir", default="eval")
    parser.add_argument("--output", default="eval/table1.json")
    args = parser.parse_args()

    aggregated = aggregate(load_results(args.input_dir))
    os.makedirs(os.path.dirname(os.path.abspath(args.output)), exist_ok=True)
    with open(args.output, "w") as f:
        json.dump(aggregated, f, indent=2, default=float)

    # Print a compact Table-1 style summary.
    for domain, priors in aggregated.items():
        print(f"\n=== {domain} ===")
        print(f"{'suite':<28}" + "".join(f"{p:>16}" for p in priors))
        all_suites = sorted({s for p in priors.values() for s in p})
        for suite in all_suites:
            row = f"{suite:<28}"
            for prior in priors:
                entry = priors[prior].get(suite)
                row += f"{'--':>16}" if entry is None else f"{entry['mean']:>10.1f}±{entry['std']:<5.1f}"
            print(row)


if __name__ == "__main__":
    main()

